 "content": "def transform(grid):
    """Bridge the two broken horizontal bars and extend their bridges vertically."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    sources = []
    bar_rows = []

    # The bars are the two rows containing many horizontal cells. Bridge
    # same-color gaps; a gap between different colors is a crossing, not a fill.
    for r, row in enumerate(grid):
        if sum(v != 0 for v in row) < 6:
            continue
        bar_rows.append(r)
        for c in range(1, w - 1):
            if row[c] == 0:
                left = next((row[j] for j in range(c - 1, -1, -1) if row[j]), None)
                right = next((row[j] for j in range(c + 1, w) if row[j]), None)
                if left is not None and left == right:
                    out[r][c] = left
                    sources.append((r, c, left))

    # Bridge cells project upward through empties until reaching an existing
    # object or earlier horizontal bar. Existing cells are not overwritten.
    for r, c, color in sources:
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color

    # Bars also project their existing horizontal colors upward at the
    # columns where those bars contain nonzero cells. This reproduces the
    # vertical runs adjacent to the bridge columns in the demonstrations.
    for r in bar_rows:
        for c in range(w):
            color = grid[r][c]
            if not color:
                continue
            # Only the leftmost edge of each solid run is not a bridge source;
            # this projection rule is refined by stopping at any occupied cell.
            # Existing bottom guide bars identify active columns.
            for rr in range(r - 1, -1, -1):
                if out[rr][c] != 0:
                    break
                out[rr][c] = color
    return out

